219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner != null) {
