226	            if (pet != null) {
227	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
228	            }
229	        }
230	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
231	    }
232	
233	    /**
234	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is
235	     * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
236	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
237	     * owners that already live in that city (e.g. {@code 'LON-SMI-0007'}).
238	     *
239	     * @param city     the owner's city
240	     * @param lastName the owner's last name
241	     * @return the assigned customer code
242	     */
243	    private String nextCustomerCode(String city, String lastName) {
244	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
245	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
246	        int sequence = (int) this.clinicService.findAllOwners().stream()
247	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
248	            .count() + 1;
249	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
250	    }
251	
252	    /**
253	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
254	     * the last two digits of the registration date's year (e.g. {@code 'LON-SMI-0007-M26'}).
255	     *
256	     * @param customerCode     the owner's assigned customer code
257	     * @param registrationDate the owner's registration date
258	     * @return the assigned membership number
259	     */
260	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
261	        String yy = String.format("%02d", registrationDate.getYear() % 100);
262	        return String.format("%s-M%s", customerCode, yy);
263	    }
264	
265	    /**
266	     * Counts the existing owners that already share the given first name and last name, comparing
267	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
268	     * the number of namesakes that existed prior to this create.
269	     *
270	     * @param firstName the new owner's first name
271	     * @param lastName  the new owner's last name
272	     * @return the number of existing owners with the same first and last name
273	     */
274	    private int countNamesakes(String firstName, String lastName) {
275	        int count = 0;
276	        for (Owner existing : this.clinicService.findAllOwners()) {
277	            if (firstName.equalsIgnoreCase(existing.getFirstName())
278	                && lastName.equalsIgnoreCase(existing.getLastName())) {
279	                count++;
280	            }
281	        }
282	        return count;
283	    }
284	
285	    /**
286	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
287	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
288	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
289	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
290	     * string is what gets stored and returned.
291	     *
292	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
293	     *
294	     * @param telephone the raw telephone value supplied by the client
295	     * @return the normalized E.164 telephone number
296	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
297	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
298	     *                                 digits after the {@code '+'})
299	     */
300	    private static String normalizeTelephone(String telephone) {
301	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
302	        String digits;
303	        if (cleaned.startsWith("+")) {
304	            digits = cleaned.substring(1);
305	        } else {
306	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
307	            digits = "61" + national;
308	        }
309	        if (!digits.matches("[0-9]{8,15}")) {
310	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
311	                "telephone could not be normalized to a valid E.164 number");
312	        }
313	        return "+" + digits;
314	    }
315	
316	    /**
317	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
318	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
319	     *
320	     * @param telephone the stored telephone value, possibly {@code null}
321	     * @return the E.164 form, or the raw value when it cannot be normalized
322	     */
323	    private static String toComparableTelephone(String telephone) {
324	        try {
325	            return normalizeTelephone(telephone);
326	        } catch (ResponseStatusException ex) {
327	            return telephone;
328	        }
329	    }
330	
331	    /**
332	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
333	     * containing at least one dot, none of the three sections containing whitespace or an
334	     * additional {@code @}.
335	     */
336	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
337	
338	    /**
339	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
340	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
341	     * value is then stored and returned lower-cased.
342	     *
343	     * @param email the raw email value supplied by the client, possibly {@code null}
344	     * @return the lower-cased email, or {@code null} when none was supplied
345	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
346	     *                                 is not a syntactically valid address
347	     */
348	    private static String normalizeEmail(String email) {
349	        if (email == null) {
350	            return null;
351	        }
352	        if (!EMAIL_PATTERN.matcher(email).matches()) {
353	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
354	                "email must be a syntactically valid address");
355	        }
356	        return email.toLowerCase(Locale.ROOT);
357	    }
358	
359	    /**
360	     * Common street-type abbreviations expanded to their full word during address normalization.
361	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
362	     */
363	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
364	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
365	
366	    /**
367	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
368	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
369	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
370	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
371	     * address comparison (household duplicate detection and the shared household id).
372	     *
373	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
374	     *
375	     * @param address the raw address supplied by the client, possibly {@code null}
376	     * @return the normalized address
377	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
378	     *                                 after normalization (required field)
379	     */
380	    private static String normalizeAddress(String address) {
381	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
382	        if (collapsed.isEmpty()) {
383	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
384	                "address must not be blank");
385	        }
386	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
387	        StringBuilder normalized = new StringBuilder();
388	        for (int i = 0; i < tokens.length; i++) {
389	            if (i > 0) {
390	                normalized.append(' ');
391	            }
392	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
393	        }
394	        return normalized.toString();
395	    }
396	
397	    /**
398	     * Determines whether the given normalized E.164 telephone is already used by any owner other
399	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
400	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
401	     * inputs representing the same number are treated as duplicates.
402	     *
403	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
404	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
405	     * @return {@code true} if another owner already uses the telephone
406	     */
407	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
408	        for (Owner existing : this.clinicService.findAllOwners()) {
409	            if (excludeId != null && excludeId.equals(existing.getId())) {
410	                continue;
411	            }
412	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
413	                return true;
414	            }
415	        }
416	        return false;
417	    }
418	
419	}
